# Shopping Cart Component with Redux Toolkit

Here's a complete shopping cart implementation with Redux Toolkit for state management:

```jsx
// store/cartSlice.js
import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  items: [],
  totalQuantity: 0,
  totalPrice: 0,
  cartOpen: false,
};

const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addItem: (state, action) => {
      const item = action.payload;
      const existingItem = state.items.find(cartItem => cartItem.id === item.id);

      if (existingItem) {
        existingItem.quantity += 1;
      } else {
        state.items.push({ ...item, quantity: 1 });
      }

      state.totalQuantity += 1;
      state.totalPrice += item.price;
    },

    removeItem: (state, action) => {
      const itemId = action.payload;
      const existingItem = state.items.find(cartItem => cartItem.id === itemId);

      if (existingItem) {
        if (existingItem.quantity > 1) {
          existingItem.quantity -= 1;
        } else {
          state.items = state.items.filter(item => item.id !== itemId);
        }

        state.totalQuantity -= 1;
        state.totalPrice -= existingItem.price;
      }
    },

    clearCart: (state) => {
      state.items = [];
      state.totalQuantity = 0;
      state.totalPrice = 0;
    },

    setCartOpen: (state, action) => {
      state.cartOpen = action.payload;
    },

    // Add this reducer to update entire cart state at once
    setCart: (state, action) => {
      const { items, totalQuantity, totalPrice } = action.payload;
      state.items = items;
      state.totalQuantity = totalQuantity;
      state.totalPrice = totalPrice;
    },
  },
});

export const {
  addItem,
  removeItem,
  clearCart,
  setCartOpen,
  setCart
} = cartSlice.actions;

export default cartSlice.reducer;
```

